const item = $input.item.json;

const platforms = (item.monitoringPlatformsCsv || '').split(',').map(p => p.trim()).filter(Boolean);
const keywords = (item.brandKeywords || '').split(',').map(k => k.trim()).filter(Boolean);

// Generate common typosquat / impersonation-style handle variants for each keyword
function buildVariants(keyword) {
  const base = keyword.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (!base) return [];
  return Array.from(new Set([
    base,
    base + 'official',
    base + 'support',
    base + '_help',
    base.replace(/o/g, '0'),
    base.length > 1 ? base.slice(0, -1) : base,
    base + '1'
  ]));
}

let handleVariants = [];
keywords.forEach(k => {
  handleVariants = handleVariants.concat(buildVariants(k));
});
handleVariants = Array.from(new Set(handleVariants));

const monitoringQueries = [];
platforms.forEach(platform => {
  keywords.forEach(keyword => {
    monitoringQueries.push({ platform, queryText: keyword, queryType: 'keyword' });
  });
  handleVariants.forEach(handle => {
    monitoringQueries.push({ platform, queryText: handle, queryType: 'handle_variant' });
  });
});

return {
  json: {
    ...item,
    handleVariants,
    monitoringQueries,
    queryBatchSize: monitoringQueries.length
  }
};

