const item = $input.item.json;
let classifications = [];
let classificationParsedSuccessfully = true;
try {
  const rawText = item.output || item.text || item.response || '[]';
  const clean = rawText.replace(/```json|```/g, '').trim();
  classifications = JSON.parse(clean);
  if (!Array.isArray(classifications)) throw new Error('not an array');
} catch (e) {
  classificationParsedSuccessfully = false;
  classifications = (item.candidateMentions || []).map(c => ({
    accountHandle: c.accountHandle,
    platform: c.platform,
    isLikelyImpersonation: true,
    impersonationType: 'Unclear',
    aiRiskScore: 50,
    redFlags: ['AI classification parsing failed - flagged for manual review as a precaution'],
    recommendedAction: 'Monitor',
    briefRationale: 'Auto-flagged: could not parse AI classification output, defaulting to manual review.'
  }));
}

return {
  json: {
    ...item,
    classifications,
    classificationParsedSuccessfully,
    classifiedCount: classifications.length
  }
};

const item = $input.item.json;
const classifications = item.classifications || [];
const candidateByHandle = {};
(item.candidateMentions || []).forEach(c => { candidateByHandle[c.accountHandle] = c; });

const now = Date.now();

const scoredThreats = classifications
  .filter(c => c.isLikelyImpersonation)
  .map(c => {
    const candidate = candidateByHandle[c.accountHandle] || {};
    const followerCount = candidate.followerCount || 0;
    const createdDate = candidate.accountCreatedDate ? new Date(candidate.accountCreatedDate).getTime() : now;
    const accountAgeDays = Math.max(0, Math.round((now - createdDate) / (1000 * 60 * 60 * 24)));
    const imageSimilarity = candidate.profileImageSimilarityScore || 0;

    // Reach factor: more followers means higher priority, capped so mega-accounts don't dominate
    const reachFactor = Math.min(20, Math.round(Math.log10(followerCount + 1) * 6));
    // New-account factor: very new accounts are riskier
    const newAccountFactor = accountAgeDays < 30 ? 15 : accountAgeDays < 90 ? 8 : 0;
    // Visual clone factor: how closely the logo or profile image matches the real brand
    const visualCloneFactor = Math.round(imageSimilarity * 0.15);
    // AI-voice scams are treated as inherently urgent regardless of reach
    const voiceScamBoost = c.impersonationType === 'AI-Voice Scam Report' ? 20 : 0;

    const compositeThreatScore = Math.max(0, Math.min(100, Math.round(
      (c.aiRiskScore || 0) * 0.6 + reachFactor + newAccountFactor + visualCloneFactor + voiceScamBoost
    )));

    let priorityTier = 'Low';
    if (compositeThreatScore >= 80) priorityTier = 'Critical';
    else if (compositeThreatScore >= 60) priorityTier = 'High';
    else if (compositeThreatScore >= 40) priorityTier = 'Medium';

    return {
      ...c,
      followerCount,
      accountAgeDays,
      compositeThreatScore,
      priorityTier
    };
  })
  .sort((a, b) => b.compositeThreatScore - a.compositeThreatScore);

const scanSummaryRows = scoredThreats.map(t => [
  item.scanId || 'N/A',
  t.platform || '',
  t.accountHandle || '',
  t.impersonationType || '',
  t.compositeThreatScore,
  t.priorityTier,
  t.recommendedAction || '',
  JSON.stringify(t.redFlags || []),
  item.scanStartedAt || ''
]);

const escalationRequired = scoredThreats.some(t => t.priorityTier === 'Critical' || t.impersonationType === 'AI-Voice Scam Report');
const topThreats = scoredThreats.slice(0, 5);

return {
  json: {
    ...item,
    scoredThreats,
    threatCount: scoredThreats.length,
    scanSummaryRows,
    topThreats,
    escalationRequired
  }
};

